//! Differential tests of the Python `re` port against fixtures generated by CPython 3.13
//! (`scripts/pyregex/gen_fixtures.py`; a sample is checked in).

use std::collections::BTreeMap;
use std::path::PathBuf;

use crate::pyregex::{ErrorKind, PyRegex, is_valid};
use serde_json::Value;

/// `tests/fixtures`, or `$PYREGEX_FIXTURES` for large one-off runs.
fn fixture_dir() -> PathBuf {
    std::env::var_os("PYREGEX_FIXTURES").map_or_else(
        || {
            [env!("CARGO_MANIFEST_DIR"), "tests", "fixtures", "pyregex"]
                .iter()
                .collect()
        },
        PathBuf::from,
    )
}

/// The Python minor version the fixtures come from (`$PYREGEX_PYTHON_MINOR`, by default
/// 13): 3.14 accepts `\z` and lets `\B` match the empty string.
fn with_fixture_python<T>(f: impl FnOnce() -> T) -> T {
    let minor = std::env::var("PYREGEX_PYTHON_MINOR")
        .ok()
        .and_then(|minor| minor.parse().ok())
        .unwrap_or(crate::context::DEFAULT_PYTHON_MINOR);
    crate::context::with_python_minor(minor, f)
}

fn fixture(name: &str) -> Vec<Value> {
    let path = fixture_dir().join(name);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{path:?}: {e}"));
    match serde_json::from_str(&text).expect("valid fixture JSON") {
        Value::Array(items) => items,
        _ => panic!("fixture is not an array"),
    }
}

fn kind_name(kind: ErrorKind) -> &'static str {
    match kind {
        ErrorKind::Re => "re",
        ErrorKind::Overflow => "overflow",
        ErrorKind::Value => "value",
        ErrorKind::Recursion => "recursion",
        ErrorKind::Type => "type",
        ErrorKind::Runtime => "runtime",
    }
}

fn short(s: &str) -> String {
    if s.chars().count() > 80 {
        format!(
            "{}... ({} chars)",
            s.chars().take(80).collect::<String>(),
            s.chars().count()
        )
    } else {
        s.to_owned()
    }
}

#[test]
fn validity_matches_cpython() {
    with_fixture_python(validity_matches_cpython_inner);
}

fn validity_matches_cpython_inner() {
    let cases = fixture("validity.json");
    let mut validity_bad = Vec::new();
    let mut kind_bad = Vec::new();
    let mut msg_bad = Vec::new();
    let mut str_bad = Vec::new();
    // Outcomes that hinge on `unicodedata.lookup` (no name table is embedded).
    let mut name_gap = Vec::new();
    let mut by_source: BTreeMap<String, usize> = BTreeMap::new();
    for case in &cases {
        let pattern = case["pattern"].as_str().unwrap();
        let expected = case["kind"].as_str().unwrap();
        *by_source
            .entry(case["source"].as_str().unwrap().to_owned())
            .or_default() += 1;
        let got = PyRegex::compile(pattern);
        assert_eq!(
            got.is_ok(),
            is_valid(pattern),
            "is_valid disagrees for {pattern:?}"
        );
        let undefined_name =
            |m: Option<&str>| m.is_some_and(|m| m.starts_with("undefined character name"));
        let same = match (&got, expected) {
            (Ok(_), "ok") => true,
            (Err(e), _) => {
                kind_name(e.kind) == expected
                    && Some(e.msg.as_str()) == case["msg"].as_str()
                    && e.pos == case["pos"].as_u64().map(|p| p as usize)
            }
            _ => false,
        };
        if !same
            && (undefined_name(case["msg"].as_str())
                || undefined_name(got.as_ref().err().map(|e| e.msg.as_str())))
        {
            name_gap.push(short(pattern));
            continue;
        }
        match (&got, expected) {
            (Ok(_), "ok") => {}
            (Ok(_), _) | (Err(_), "ok") => validity_bad.push(format!(
                "{:?}: python={expected} {:?} rust={:?}",
                short(pattern),
                case["str"],
                got.as_ref().err()
            )),
            (Err(e), _) => {
                if kind_name(e.kind) != expected {
                    kind_bad.push(format!(
                        "{:?}: python={expected} rust={e:?}",
                        short(pattern)
                    ));
                    continue;
                }
                let msg = case["msg"].as_str().unwrap();
                let pos = case["pos"].as_u64().map(|p| p as usize);
                if e.msg != msg || e.pos != pos {
                    msg_bad.push(format!(
                        "{:?}: python=({msg:?}, {pos:?}) rust=({:?}, {:?})",
                        short(pattern),
                        e.msg,
                        e.pos
                    ));
                } else if e.kind == ErrorKind::Re
                    && e.python_str(pattern) != case["str"].as_str().unwrap()
                {
                    str_bad.push(format!("{:?}: {:?}", short(pattern), e.python_str(pattern)));
                }
            }
        }
    }
    let n = cases.len();
    let errors = cases.iter().filter(|c| c["kind"] != "ok").count();
    println!("validity fixture: {n} patterns ({errors} raising) by source {by_source:?}");
    println!(
        "  \\N{{name}} lookups not decidable without a name table: {} {:?}",
        name_gap.len(),
        name_gap
    );
    println!(
        "  validity agreement: {}/{} decidable; exception-kind mismatches: {}; msg/pos mismatches: {}; str() mismatches: {}",
        n - name_gap.len() - validity_bad.len(),
        n - name_gap.len(),
        kind_bad.len(),
        msg_bad.len(),
        str_bad.len()
    );
    for line in validity_bad
        .iter()
        .chain(&kind_bad)
        .chain(&msg_bad)
        .chain(&str_bad)
        .take(60)
    {
        println!("  MISMATCH {line}");
    }
    assert!(
        validity_bad.is_empty() && kind_bad.is_empty() && msg_bad.is_empty() && str_bad.is_empty()
    );
}

#[test]
fn search_matches_cpython() {
    with_fixture_python(search_matches_cpython_inner);
}

fn search_matches_cpython_inner() {
    let cases = fixture("matching.json");
    let mut wrong = Vec::new();
    // Documented gap: case-insensitive backreferences compare by simple case
    // folding in fancy-regex, by `str.lower()` in `_sre`.
    let mut casei_backref = Vec::new();
    let mut errs: BTreeMap<String, (usize, String)> = BTreeMap::new();
    let mut compiled: BTreeMap<String, PyRegex> = BTreeMap::new();
    for case in &cases {
        let pattern = case["pattern"].as_str().unwrap();
        let text = case["text"].as_str().unwrap();
        let expected = case["match"].as_bool().unwrap();
        let re = compiled
            .entry(pattern.to_owned())
            .or_insert_with(|| PyRegex::compile(pattern).expect("fixture pattern compiles"));
        match re.search(text) {
            Ok(m) if m == expected => {}
            Ok(m) => {
                let line = format!(
                    "{pattern:?} on {text:?}: python={expected} rust={m} via {:?}",
                    re.translated()
                );
                let translated = re.translated().unwrap_or_default();
                let casei_ref = translated
                    .match_indices(r"(?i:\")
                    .any(|(i, _)| translated[i + 5..].starts_with(|c: char| c.is_ascii_digit()));
                if casei_ref {
                    casei_backref.push(line);
                } else {
                    wrong.push(line);
                }
            }
            Err(e) => {
                let key: String = e
                    .replace(|c: char| c.is_ascii_digit(), "#")
                    .chars()
                    .take(70)
                    .collect();
                let slot = errs.entry(key).or_insert_with(|| {
                    (
                        0,
                        format!(
                            "{:?} -> {:?}",
                            short(pattern),
                            re.translated().map(|t| short(&t))
                        ),
                    )
                });
                slot.0 += 1;
            }
        }
    }
    let n = cases.len();
    let n_err: usize = errs.values().map(|v| v.0).sum();
    println!(
        "matching fixture: {n} pairs over {} patterns; agree {}/{n}; wrong {}; case-insensitive backref gap {}; engine errors {n_err}",
        compiled.len(),
        n - wrong.len() - casei_backref.len() - n_err,
        wrong.len(),
        casei_backref.len()
    );
    for line in &casei_backref {
        println!("  CASEI-BACKREF {line}");
    }
    for (e, (count, example)) in &errs {
        println!("  ERR x{count}: {e}\n      e.g. {example}");
    }
    for line in wrong.iter().take(60) {
        println!("  MISMATCH {line}");
    }
    assert!(wrong.is_empty(), "{} wrong results", wrong.len());
}

fn contains(ranges: &[(u32, u32)], cp: u32) -> bool {
    let i = ranges.partition_point(|&(_, hi)| hi < cp);
    ranges.get(i).is_some_and(|&(lo, _)| lo <= cp)
}

#[test]
fn character_classes_match_cpython() {
    with_fixture_python(character_classes_match_cpython_inner);
}

fn character_classes_match_cpython_inner() {
    let cases = fixture("classes.json");
    let mut total_bad = 0;
    for case in &cases {
        let pattern = case["pattern"].as_str().unwrap();
        let search = case["search"].as_str().unwrap();
        let ranges: Vec<(u32, u32)> = case["ranges"]
            .as_array()
            .unwrap()
            .iter()
            .map(|r| (r[0].as_u64().unwrap() as u32, r[1].as_u64().unwrap() as u32))
            .collect();
        let re = PyRegex::compile(search).expect("compiles");
        let mut bad = Vec::new();
        let mut buf = [0u8; 4];
        for c in (0..=0x10FFFFu32).filter_map(char::from_u32) {
            let got = re.search(c.encode_utf8(&mut buf)).expect("search");
            if got != contains(&ranges, c as u32) {
                bad.push(c as u32);
            }
        }
        if !bad.is_empty() {
            println!(
                "  CLASS {pattern:?}: {} code points differ, e.g. {:x?}",
                bad.len(),
                &bad[..bad.len().min(12)]
            );
        }
        total_bad += bad.len();
    }
    println!(
        "class fixture: {} patterns x 1,112,064 code points; differing code points: {total_bad}",
        cases.len()
    );
}

#[test]
fn casefold_matches_cpython() {
    with_fixture_python(casefold_matches_cpython_inner);
}

fn casefold_matches_cpython_inner() {
    let cases = fixture("casefold.json");
    let mut bad = Vec::new();
    let mut checks = 0;
    for case in &cases {
        let pattern = case["pattern"].as_str().unwrap();
        let re = PyRegex::compile(&format!("{pattern}\\Z")).expect("compiles");
        let mut buf = [0u8; 4];
        for (key, expected) in [("match", true), ("nomatch", false)] {
            for c in case[key].as_str().unwrap().chars() {
                checks += 1;
                // anchor at the start too: the fixture used re.fullmatch
                let got = re.search(c.encode_utf8(&mut buf)).expect("search");
                if got != expected {
                    bad.push(format!(
                        "{pattern:?} vs U+{:04X}: python={expected}",
                        c as u32
                    ));
                }
            }
        }
    }
    println!(
        "casefold fixture: {} patterns, {checks} checks, {} differ",
        cases.len(),
        bad.len()
    );
    for line in bad.iter().take(40) {
        println!("  CASEFOLD {line}");
    }
}

fn ranges_of(v: &Value) -> Vec<(u32, u32)> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|r| (r[0].as_u64().unwrap() as u32, r[1].as_u64().unwrap() as u32))
        .collect()
}

/// `str.isidentifier`, `str.isalpha` and `str.isprintable` (via `repr`) for
/// every non-ASCII code point, observed through compile results and messages.
#[test]
fn unicode_properties_match_cpython() {
    with_fixture_python(unicode_properties_match_cpython_inner);
}

fn unicode_properties_match_cpython_inner() {
    let path = fixture_dir().join("chars.json");
    let chars: Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let start = ranges_of(&chars["ident_start"]);
    let cont = ranges_of(&chars["ident_continue"]);
    let alpha = ranges_of(&chars["alpha"]);
    let printable = ranges_of(&chars["printable"]);
    let mut bad: BTreeMap<&str, Vec<u32>> = BTreeMap::new();
    for c in (0x80..=0x10FFFFu32).filter_map(char::from_u32) {
        let cp = c as u32;
        if is_valid(&format!("(?P<{c}>x)")) != contains(&start, cp) {
            bad.entry("isidentifier(c)").or_default().push(cp);
        }
        if is_valid(&format!("(?P<a{c}>x)")) != contains(&cont, cp) {
            bad.entry("isidentifier('a'+c)").or_default().push(cp);
        }
        let flag_msg = PyRegex::compile(&format!("(?i{c})")).unwrap_err().msg;
        if (flag_msg == "unknown flag") != contains(&alpha, cp) {
            bad.entry("isalpha(c)").or_default().push(cp);
        }
        let repr_msg = PyRegex::compile(&format!("(?P<-{c}>x)")).unwrap_err().msg;
        if repr_msg.contains(c) != contains(&printable, cp) {
            bad.entry("isprintable(c)").or_default().push(cp);
        }
    }
    for (what, cps) in &bad {
        println!(
            "  {what}: {} code points differ, e.g. {:x?}",
            cps.len(),
            &cps[..cps.len().min(10)]
        );
    }
    println!(
        "unicode properties: 4 x 1,111,936 non-ASCII code points; {} differ",
        bad.values().map(Vec::len).sum::<usize>()
    );
    assert!(bad.is_empty());
}
